package com.ptms.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<?> nf(ResourceNotFoundException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}@ExceptionHandler(BusinessRuleException.class) ResponseEntity<?> br(BusinessRuleException e){return ResponseEntity.status(409).body(Map.of("message",e.getMessage()));}}
